import{_ as d,o as e,c as o,ag as a}from"./chunks/framework.D7xI0JV8.js";const u=JSON.parse('{"title":"API Overview","description":"","frontmatter":{},"headers":[],"relativePath":"api-overview.md","filePath":"api-overview.md"}'),r={name:"api-overview.md"};function i(c,t,l,n,s,p){return e(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="api-overview" tabindex="-1">API Overview <a class="header-anchor" href="#api-overview" aria-label="Permalink to &quot;API Overview&quot;">​</a></h1><p>The zkde.fi API is the programmatic surface of the <a href="/docs/proof-pipeline.html">proof pipeline</a>. Every endpoint that triggers execution passes through the circuit screening and policy gate layer before returning a calldata response. Read-only endpoints return current proof state, reputation state, and settlement status. Mutation endpoints that trigger capital movement require valid proof context.</p><p>Live verification of the full API surface: <strong><a href="https://zkde.fi/test" target="_blank" rel="noreferrer">zkde.fi/test</a></strong></p><h2 id="base-urls" tabindex="-1">Base URLs <a class="header-anchor" href="#base-urls" aria-label="Permalink to &quot;Base URLs&quot;">​</a></h2><ul><li>App: <code>https://zkde.fi</code></li><li>Core API host: <code>https://zkde.fi/api/v1</code></li><li>zkdefi namespace prefix: under core host, use <code>/zkdefi/{resource}</code></li></ul><h2 id="authentication-model-grounded" tabindex="-1">Authentication Model (Grounded) <a class="header-anchor" href="#authentication-model-grounded" aria-label="Permalink to &quot;Authentication Model (Grounded)&quot;">​</a></h2><h3 id="wallet-owner-header" tabindex="-1">Wallet-owner header <a class="header-anchor" href="#wallet-owner-header" aria-label="Permalink to &quot;Wallet-owner header&quot;">​</a></h3><ul><li>Header: <code>X-Wallet-Address</code></li><li>Used on protected user-mutating paths where server enforces caller-address match.</li></ul><h3 id="admin-header" tabindex="-1">Admin header <a class="header-anchor" href="#admin-header" aria-label="Permalink to &quot;Admin header&quot;">​</a></h3><ul><li>Header: <code>X-Admin-Key</code></li><li>Used on admin-only/destructive operations.</li></ul><h3 id="important-note" tabindex="-1">Important note <a class="header-anchor" href="#important-note" aria-label="Permalink to &quot;Important note&quot;">​</a></h3><p>Not every POST/PUT endpoint is currently wallet-header-protected by dependency wiring, so integrators should treat auth as endpoint-specific and follow this reference plus release notes.</p><pre class="mermaid" data-mermaid-source="flowchart%20LR%0A%20%20C%5BClient%5D%20--%3E%20R%7BEndpoint%20type%7D%0A%20%20R%20--%3E%7CPublic%2FRead%7C%20P%5BNo%20auth%20header%20required%5D%0A%20%20R%20--%3E%7CUser-protected%20write%7C%20W%5BX-Wallet-Address%5D%0A%20%20R%20--%3E%7CAdmin-only%7C%20A%5BX-Admin-Key%5D">flowchart LR
  C[Client] --&gt; R{Endpoint type}
  R --&gt;|Public/Read| P[No auth header required]
  R --&gt;|User-protected write| W[X-Wallet-Address]
  R --&gt;|Admin-only| A[X-Admin-Key]</pre><h2 id="core-health-and-metadata" tabindex="-1">Core Health And Metadata <a class="header-anchor" href="#core-health-and-metadata" aria-label="Permalink to &quot;Core Health And Metadata&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th><th>Typical auth</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/health</code></td><td>Service liveness</td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/phase4a/contracts</code></td><td>Contract address metadata</td><td>Public</td></tr></tbody></table><h2 id="identity-reputation-passport-compliance" tabindex="-1">Identity, Reputation, Passport, Compliance <a class="header-anchor" href="#identity-reputation-passport-compliance" aria-label="Permalink to &quot;Identity, Reputation, Passport, Compliance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th><th>Typical auth</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/reputation/tiers</code></td><td>Tier definitions</td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/reputation/user/{address}</code></td><td>User reputation snapshot</td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/reputation/proofs/{address}</code></td><td>FICO pack proof status (all 5 proofs)</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/reputation/upgrade-tier</code></td><td>Tier upgrade request</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/reputation/proof/solvency</code></td><td>Generate solvency proof</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/reputation/proof/risk-passport</code></td><td>Generate risk passport tier proof</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/reputation/proof/performance</code></td><td>Generate trader performance proof</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/reputation/proof/strategy-integrity</code></td><td>Generate strategy integrity proof</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/reputation/proof/execution-integrity</code></td><td>Generate execution integrity proof</td><td>App flow</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/risk_passport/user/{address}</code></td><td>User passport</td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/risk_passport/pool/{pool_id}</code></td><td>Pool passport</td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/risk_profile/{address}</code></td><td>Aggregated risk profile bundle</td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/compliance/profiles/{user_address}</code></td><td>Compliance profiles</td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/linked_addresses/{address}</code></td><td>Linked-address map</td><td>Public</td></tr><tr><td><code>PUT</code></td><td><code>/api/v1/zkdefi/linked_addresses</code></td><td>Update linked addresses</td><td>App flow</td></tr></tbody></table><h2 id="onboarding-and-agent-registration" tabindex="-1">Onboarding And Agent Registration <a class="header-anchor" href="#onboarding-and-agent-registration" aria-label="Permalink to &quot;Onboarding And Agent Registration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th><th>Typical auth</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/onboarding/generate_authorization</code></td><td>Generate onboarding authorization payload</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/onboarding/submit_agent</code></td><td>Submit onboarding/agent registration</td><td>App flow</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/onboarding/status/{user_address}</code></td><td>Onboarding status</td><td>Public</td></tr></tbody></table><h2 id="orchestration-deploy-and-utilities" tabindex="-1">Orchestration (Deploy And Utilities) <a class="header-anchor" href="#orchestration-deploy-and-utilities" aria-label="Permalink to &quot;Orchestration (Deploy And Utilities)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th><th>Typical auth</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/orchestration/deploy</code></td><td>Build/record deploy orchestration flow</td><td>App flow</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/orchestration/receipt/{receipt_id}</code></td><td>Read deploy receipt</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/orchestration/receipt/confirm</code></td><td>Attach tx hash to receipt</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/orchestration/swap-strk-to-usdc</code></td><td>Build STRK to USDC calldata</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/orchestration/faucet/eth</code></td><td>Testnet ETH faucet utility</td><td>App flow</td></tr></tbody></table><h2 id="session-keys-and-rebalancer" tabindex="-1">Session Keys And Rebalancer <a class="header-anchor" href="#session-keys-and-rebalancer" aria-label="Permalink to &quot;Session Keys And Rebalancer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th><th>Typical auth</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/session_keys/grant</code></td><td>Build session grant request</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/session_keys/grant/confirm</code></td><td>Confirm granted session</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/session_keys/revoke</code></td><td>Build session revoke request</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/session_keys/revoke/confirm</code></td><td>Confirm revoke</td><td>App flow</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/session_keys/list/{owner_address}</code></td><td>List sessions</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/rebalancer/propose</code></td><td>Create rebalance proposal</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/rebalancer/check</code></td><td>Run risk/anomaly checks</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/rebalancer/advisory-check</code></td><td>Non-blocking policy check</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/rebalancer/prepare</code></td><td>Prepare execution context</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/rebalancer/execute</code></td><td>Execute rebalance</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/rebalancer/autonomous/start</code></td><td>Start autonomous mode</td><td><code>X-Wallet-Address</code></td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/rebalancer/autonomous/stop</code></td><td>Stop autonomous mode</td><td><code>X-Wallet-Address</code></td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/rebalancer/autonomous/pause/{user_address}</code></td><td>Pause autonomous mode</td><td><code>X-Wallet-Address</code></td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/rebalancer/autonomous/resume/{user_address}</code></td><td>Resume autonomous mode</td><td><code>X-Wallet-Address</code></td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/rebalancer/autonomous/all</code></td><td>Fleet status</td><td><code>X-Admin-Key</code></td></tr></tbody></table><h2 id="auth-session-dual-wallet-bind" tabindex="-1">Auth Session (Dual-Wallet Bind) <a class="header-anchor" href="#auth-session-dual-wallet-bind" aria-label="Permalink to &quot;Auth Session (Dual-Wallet Bind)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th><th>Typical auth</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/auth/session/start</code></td><td>Start dual-wallet auth session</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/auth/session/complete</code></td><td>Complete dual-wallet auth session</td><td>App flow</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/auth/session/{starknet_address}</code></td><td>Read active auth session</td><td>Public</td></tr><tr><td><code>DELETE</code></td><td><code>/api/v1/zkdefi/auth/session/{starknet_address}</code></td><td>Revoke active auth session</td><td>App flow</td></tr></tbody></table><h2 id="trade-market-and-ekubo" tabindex="-1">Trade, Market, And Ekubo <a class="header-anchor" href="#trade-market-and-ekubo" aria-label="Permalink to &quot;Trade, Market, And Ekubo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th><th>Typical auth</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/market/surface</code></td><td>Market surface bundle</td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/ekubo/capabilities</code></td><td>Ekubo capability metadata</td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/ekubo/positions</code></td><td>Ekubo position view</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/ekubo/swap/quote</code></td><td>Swap quote</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/ekubo/swap/build</code></td><td>Build swap tx</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/ekubo/lp/add/build</code></td><td>Build LP add tx</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/ekubo/lp/remove/build</code></td><td>Build LP remove tx</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/ekubo/lp/collect-fees/build</code></td><td>Build fee-collect tx</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/ekubo/lp/recommend</code></td><td>LP recommendation</td><td>App flow</td></tr></tbody></table><h2 id="reputation-based-lending" tabindex="-1">Reputation-Based Lending <a class="header-anchor" href="#reputation-based-lending" aria-label="Permalink to &quot;Reputation-Based Lending&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th><th>Typical auth</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/lending/pool</code></td><td>Lending pool stats</td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/lending/positions/{address}</code></td><td>User lending positions</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/lending/supply</code></td><td>Build supply calldata</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/lending/borrow</code></td><td>Build borrow calldata (attestation-based)</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/lending/repay</code></td><td>Build repay calldata</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/lending/withdraw</code></td><td>Build withdraw calldata</td><td>App flow</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/lending/health/{address}</code></td><td>Health factor context</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/lending/proof/credit-eligibility</code></td><td>Credit eligibility proof generation</td><td>App flow</td></tr></tbody></table><h2 id="zkml-inference-and-circuit-scan" tabindex="-1">zkML Inference And Circuit Scan <a class="header-anchor" href="#zkml-inference-and-circuit-scan" aria-label="Permalink to &quot;zkML Inference And Circuit Scan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th><th>Typical auth</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/zkml/scan</code></td><td>Scan model/circuit inputs and return zkML risk signals</td><td>App flow</td></tr></tbody></table><h2 id="privacy-and-state" tabindex="-1">Privacy And State <a class="header-anchor" href="#privacy-and-state" aria-label="Permalink to &quot;Privacy And State&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th><th>Typical auth</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/full_privacy/deposit/generate_commitment</code></td><td>Privacy commitment generation</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/full_privacy/deposit/register_commitment</code></td><td>Register commitment</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/full_privacy/withdraw/generate_proof</code></td><td>Withdrawal proof generation</td><td>App flow</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/full_privacy/merkle/root</code></td><td>Merkle root state</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/full_privacy/merkle/reset</code></td><td>Merkle reset</td><td><code>X-Admin-Key</code></td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/privacy/deposit</code></td><td>Unified privacy deposit</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/privacy/withdraw</code></td><td>Unified privacy withdraw</td><td>App flow</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/wallet/state/{user_address}</code></td><td>Wallet state snapshot</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/execution/preflight</code></td><td>Preflight execution checks</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/state/manual-wallet-event</code></td><td>Manual wallet event injection</td><td>App flow</td></tr></tbody></table><h2 id="policy-relayer-and-ledger" tabindex="-1">Policy, Relayer, And Ledger <a class="header-anchor" href="#policy-relayer-and-ledger" aria-label="Permalink to &quot;Policy, Relayer, And Ledger&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th><th>Typical auth</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/policy/vault/{user_address}</code></td><td>Read vault policy</td><td>Public</td></tr><tr><td><code>PUT</code></td><td><code>/api/v1/zkdefi/policy/vault/{user_address}</code></td><td>Update vault policy</td><td><code>X-Wallet-Address</code></td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/policy/compile</code></td><td>Compile policy</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/policy/reset/{user_address}</code></td><td>Reset policy state</td><td><code>X-Admin-Key</code></td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/relayer/request</code></td><td>Relay request</td><td>App flow</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/relayer/pending/{address}</code></td><td>Pending relay queue</td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/ledger/transfers</code></td><td>Ledger transfers</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/ledger/demo-credit</code></td><td>Demo credit path</td><td>App flow</td></tr></tbody></table><h2 id="integrator-apis-outside-zkdefi" tabindex="-1">Integrator APIs Outside <code>/zkdefi</code> <a class="header-anchor" href="#integrator-apis-outside-zkdefi" aria-label="Permalink to &quot;Integrator APIs Outside \`/zkdefi\`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th><th>Typical auth</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/v1/identity/credit-proof</code></td><td>Identity credit proof flow</td><td>App flow</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/identity/commitment/{commitment}</code></td><td>Commitment lookup</td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/agents/models/list</code></td><td>Model catalog</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/agents/create</code></td><td>Create agent entry</td><td>App flow</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/strategies/price/live</code></td><td>Price feed</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/strategies/recommend</code></td><td>Strategy recommendation</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/deployments/execute</code></td><td>Deployment execution</td><td>App flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/vault/execute</code></td><td>Vault execution path</td><td>App flow</td></tr></tbody></table><h2 id="experimental-scope-changing-faster" tabindex="-1">Experimental Scope (Changing Faster) <a class="header-anchor" href="#experimental-scope-changing-faster" aria-label="Permalink to &quot;Experimental Scope (Changing Faster)&quot;">​</a></h2><ul><li><code>GET /api/v1/phase4a/status</code></li><li><code>GET /api/v1/phase4a/orchestrated/dashboard</code></li><li><code>GET /api/v1/phase4a/rebalancer/stats</code></li><li><code>GET /api/v1/vault-live/positions/{user_address}</code></li><li><code>POST /api/v1/vault-live/rebalance</code></li><li><code>POST /api/v1/vault-live/execute</code></li><li><code>GET /api/v1/zkdefi/sim/health</code></li><li><code>GET /api/v1/zkdefi/sim/state</code></li><li><code>GET /api/v1/zkdefi/sim/events</code></li><li><code>GET /api/v1/zkdefi/sim/contracts</code></li></ul><p>Treat these as version-sensitive and monitor release notes before depending on response contracts.</p><h2 id="legal-and-compliance-posture" tabindex="-1">Legal And Compliance Posture <a class="header-anchor" href="#legal-and-compliance-posture" aria-label="Permalink to &quot;Legal And Compliance Posture&quot;">​</a></h2><p>These docs describe technical capabilities and API behavior only. They are not legal advice, not investment advice, and not a representation that any user automatically meets regulatory requirements in any jurisdiction.</p><p>Next: <a href="/docs/developers.html">Developers</a> | <a href="/docs/architecture-summary.html">Architecture summary</a> | <a href="/docs/troubleshooting.html">Troubleshooting</a></p>`,43)])])}const f=d(r,[["render",i]]);export{u as __pageData,f as default};
